#include <algorithm>
#include <functional>
#include <stdexcept>
#include <utility>
#include <cassert>
using namespace std;

bool balanced(const string& text) {
    stack<char> s;
    for (char c : text) {
        if (c == '(') s.push(c);
        else if (c == ')') {
            if (s.empty()) return false;
            s.pop();
        }
    }
    return s.empty();
}
int main(){
cout << boolalpha << balanced("(())") << " " << balanced("(()") << "\n";
}

