#include <iostream>
#include <vector>
#include <string>
#include <queue>
#include <stack>
#include <unordered_map>
#include <unordered_set>
#include <algorithm>
#include <functional>
#include <stdexcept>
#include <utility>
#include <cassert>
using namespace std;
void mergeRange(vector<int>& a,int l,int m,int r) {
    vector<int> temp;temp.reserve(r-l);int i=l,j=m;
    while(i<m && j<r) temp.push_back(a[i]<=a[j]?a[i++]:a[j++]);
    while(i<m) temp.push_back(a[i++]);
    while(j<r) temp.push_back(a[j++]);
    copy(temp.begin(),temp.end(),a.begin()+l);
}

void mergeSort(vector<int>& a, int l, int r) {
    if (r-l <= 1) return;
    int mid=l+(r-l)/2;
    mergeSort(a,l,mid);
    mergeSort(a,mid,r);
    mergeRange(a,l,mid,r);
}
int main(){
vector<int>a{5,2,4,1}; mergeSort(a,0,a.size()); for(int x:a)cout<<x<<" ";cout<<"\n";
}

#include <iostream>
#include <vector>
#include <string>
#include <queue>
#include <stack>
#include <unordered_map>
#include <unordered_set>
#include <algorithm>
#include <functional>
#include <stdexcept>
#include <utility>
#include <cassert>
using namespace std;

int partitionOnce(vector<int>& a, int l, int r) {
    int pivot=a[r-1], i=l;
    for (int j=l; j<r-1; ++j) {
        if (a[j]<pivot) swap(a[i++],a[j]);
    }
    swap(a[i],a[r-1]);
    return i;
}
int main(){
vector<int>a{5,2,1,4};cout<<partitionOnce(a,0,a.size())<<"\n";for(int x:a)cout<<x<<" ";cout<<"\n";
}

